#include <bits/stdc++.h>
using namespace std;
int main(){
    vector<int> a={2,2};
    vector<char> ops;
    for(int v:a){ for(int i=0;i<v;i++)ops.push_back('A'); for(int i=0;i<v;i++)ops.push_back('B');}
    int N=ops.size()+1;
    for(int x=0;x<N;x++){
        int w=x+1;
        if(w>22) break;
        vector<vector<int>> minsets;
        for(int mask=1; mask<(1<<w); mask++){
            vector<int> cur(w);
            for(int j=0;j<w;j++) cur[j]=(mask>>j)&1;
            for(int t=0;t<x;t++){
                vector<int> nxt(cur.size()-1);
                for(int j=0;j<(int)cur.size()-1;j++){
                    if(ops[t]=='A') nxt[j]=cur[j]&cur[j+1];
                    else nxt[j]=cur[j]|cur[j+1];
                }
                cur=nxt;
            }
            if(cur[0]==1){
                bool minimal=true;
                for(int sub=(mask-1)&mask; sub; sub=(sub-1)&mask){
                    vector<int> c(w);
                    for(int j=0;j<w;j++) c[j]=(sub>>j)&1;
                    for(int t=0;t<x;t++){
                        vector<int> nx(c.size()-1);
                        for(int j=0;j<(int)c.size()-1;j++){
                            if(ops[t]=='A') nx[j]=c[j]&c[j+1]; else nx[j]=c[j]|c[j+1];
                        }
                        c=nx;
                    }
                    if(c[0]==1){minimal=false;break;}
                }
                if(minimal){
                    vector<int> s;
                    for(int j=0;j<w;j++) if(mask>>j&1) s.push_back(j);
                    minsets.push_back(s);
                }
            }
        }
        printf("x=%d:",x);
        for(auto&s:minsets){printf(" {");for(int j:s)printf("%d,",j);printf("}");}
        printf("\n");
    }
    return 0;
}

