#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int n,m,q;
vector<ll> p;
int LOGN;
vector<vector<int>> st; // sparse table index of min
void buildST(){
    LOGN=1; while((1<<LOGN)<=n) LOGN++;
    st.assign(LOGN, vector<int>(n+1,0));
    for(int i=1;i<=n;i++) st[0][i]=i;
    for(int k=1;k<LOGN;k++)
        for(int i=1;i+(1<<k)-1<=n;i++){
            int a=st[k-1][i], b=st[k-1][i+(1<<(k-1))];
            st[k][i] = (p[a]<=p[b])?a:b;
        }
}
inline ll getmin(int l,int r){
    int k=31-__builtin_clz(r-l+1);
    int a=st[k][l], b=st[k][r-(1<<k)+1];
    return min(p[a],p[b]);
}
int main(){
    scanf("%d %d %d",&n,&m,&q);
    p.assign(n+1,0);
    for(int i=1;i<=n;i++) scanf("%lld",&p[i]);
    vector<int> a(m);
    for(int i=0;i<m;i++) scanf("%d",&a[i]);
    // build ops
    vector<char> ops; ops.reserve(n-1);
    for(int v:a){ for(int i=0;i<v;i++) ops.push_back('A'); for(int i=0;i<v;i++) ops.push_back('B'); }
    vector<int> Larr(n),loarr(n),hiarr(n);
    {
        int L=1,lo=0,hi=0;
        Larr[0]=1;loarr[0]=0;hiarr[0]=0;
        for(int t=0;t+1<n;t++){
            if(ops[t]=='A'){ if(lo<hi) lo++; else L++; }
            else hi++;
            Larr[t+1]=L;loarr[t+1]=lo;hiarr[t+1]=hi;
        }
    }
    buildST();
    bool allOne=true; for(int v:a) if(v!=1) allOne=false;
    // special all a==1: L=2
    vector<ll> prefM(n+2,0), prefAdj(n+2,0);
    if(allOne){
        // M[j]=min(p[j],p[j+1]) j=1..n-1
        for(int j=1;j<=n-1;j++) prefM[j]=prefM[j-1]+min(p[j],p[j+1]);
        // Adj[t]=max(M[t],M[t+1]) t=1..n-2
        auto M=[&](int j){return min(p[j],p[j+1]);};
        for(int t=1;t<=n-2;t++) prefAdj[t]=prefAdj[t-1]+max(M(t),M(t+1));
        for(int t=n-1;t<=n;t++) prefAdj[t]=prefAdj[t-1];
    }
    while(q--){
        int x,l,r; scanf("%d %d %d",&x,&l,&r);
        ll ans=0;
        if(allOne){
            if(x%2==1){ int k=(x-1)/2; ans=prefM[r+k]-prefM[l+k-1]; }
            else { int k=x/2; int t1=l+k-1,t2=r+k-1; ans=prefAdj[t2]-prefAdj[t1-1]; }
        } else {
            int L=Larr[x],lo=loarr[x],hi=hiarr[x];
            int W=hi-lo;
            int jstart=l+lo, jend=r+hi;
            vector<ll> mm; mm.reserve(jend-jstart+1);
            for(int j=jstart;j<=jend;j++) mm.push_back(getmin(j,j+L-1));
            int s=W+1;
            deque<int> dq;
            ll sum=0;
            for(int idx=0;idx<(int)mm.size();idx++){
                while(!dq.empty() && mm[dq.back()]<=mm[idx]) dq.pop_back();
                dq.push_back(idx);
                if(dq.front()<=idx-s) dq.pop_front();
                if(idx>=s-1) sum+=mm[dq.front()];
            }
            ans=sum;
        }
        printf("%lld\n",ans);
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// brute vs formula self test
int main(){
    mt19937 rng(12345);
    for(int iter=0; iter<20000; iter++){
        // n odd, n-1 = 2*sum a
        int m = rng()%4+1;
        int sum=0; vector<int> a(m);
        for(int i=0;i<m;i++){ a[i]=rng()%4+1; sum+=a[i]; }
        int n = 2*sum+1;
        if(n>13) continue;
        vector<ll> p(n+1);
        for(int i=1;i<=n;i++) p[i]=rng()%10+1;
        // build ops
        vector<char> ops;
        for(int v:a){ for(int i=0;i<v;i++)ops.push_back('A'); for(int i=0;i<v;i++)ops.push_back('B'); }
        // brute states arrays after each x
        vector<vector<ll>> arrs; arrs.push_back(vector<ll>(p.begin()+1,p.end()));
        { vector<ll> cur(p.begin()+1,p.end());
          for(char c:ops){ vector<ll> nx; for(int i=0;i+1<(int)cur.size();i++){ if(c=='A')nx.push_back(min(cur[i],cur[i+1])); else nx.push_back(max(cur[i],cur[i+1])); } cur=nx; arrs.push_back(cur);} }
        // formula: compute states by sim param
        vector<int> Larr(n),loarr(n),hiarr(n);
        { int L=1,lo=0,hi=0; Larr[0]=1;loarr[0]=0;hiarr[0]=0;
          for(int t=0;t+1<n;t++){ if(ops[t]=='A'){ if(lo<hi)lo++; else L++; } else hi++; Larr[t+1]=L;loarr[t+1]=lo;hiarr[t+1]=hi; } }
        // sparse table min
        int LOG=1; while((1<<LOG)<=n)LOG++;
        vector<vector<int>> st(LOG, vector<int>(n+1));
        for(int i=1;i<=n;i++)st[0][i]=i;
        for(int k=1;k<LOG;k++)for(int i=1;i+(1<<k)-1<=n;i++){int u=st[k-1][i],v=st[k-1][i+(1<<(k-1))];st[k][i]=p[u]<=p[v]?u:v;}
        auto gmin=[&](int l,int r){int k=31-__builtin_clz(r-l+1);int u=st[k][l],v=st[k][r-(1<<k)+1];return min(p[u],p[v]);};
        for(int x=1;x<n;x++){
            int N=n-x;
            int L=Larr[x],lo=loarr[x],hi=hiarr[x];
            // compute formula values for all i
            vector<ll> f(N+1);
            for(int i=1;i<=N;i++){
                ll best=LLONG_MIN;
                for(int j=i+lo;j<=i+hi;j++){ if(j<1||j+L-1>n){best=LLONG_MIN;break;} best=max(best,gmin(j,j+L-1)); }
                f[i]=best;
            }
            for(int i=1;i<=N;i++){
                if(f[i]!=arrs[x][i-1]){
                    printf("MISMATCH iter=%d n=%d m=%d x=%d i=%d formula=%lld brute=%lld L=%d lo=%d hi=%d\n",iter,n,m,x,i,f[i],arrs[x][i-1],L,lo,hi);
                    printf("p:"); for(int t=1;t<=n;t++)printf(" %lld",p[t]); printf("\na:"); for(int v:a)printf(" %d",v); printf("\n");
                    return 0;
                }
            }
        }
    }
    printf("ALL OK\n");
    return 0;
}

