using namespace std;
typedef long long ll;
int n,m,q;
vector<ll> p;
int LOGN;
vector<vector<int>> st;
void buildST(){
    LOGN=1; while((1<<LOGN)<=n) LOGN++;
    st.assign(LOGN, vector<int>(n+1,0));
    for(int i=1;i<=n;i++) st[0][i]=i;
    for(int k=1;k<LOGN;k++)
        for(int i=1;i+(1<<k)-1<=n;i++){
            int a=st[k-1][i], b=st[k-1][i+(1<<(k-1))];
            st[k][i] = (p[a]<=p[b])?a:b;
