    int a=st[k][l], b=st[k][r-(1<<k)+1];
    return min(p[a],p[b]);
}
// segment tree over m array
struct SegTree{
    int M; vector<ll> t;
    void build(vector<ll>& m){ // m 0-indexed size M
        M=m.size(); t.assign(2*M,LLONG_MIN);
        for(int i=0;i<M;i++) t[M+i]=m[i];
        for(int i=M-1;i>=1;i--) t[i]=max(t[2*i],t[2*i+1]);
    }
    ll qmax(int l,int r){ // inclusive 0-indexed
        l+=M; r+=M; ll res=LLONG_MIN;
        while(l<=r){ if(l&1) res=max(res,t[l++]); if(!(r&1)) res=max(res,t[r--]); l>>=1; r>>=1; }
        return res;
    }
};
struct Entry{int idx,lo,hi,l,r;};
int main(){
    scanf("%d %d %d",&n,&m,&q);
    p.assign(n+1,0);
    for(int i=1;i<=n;i++) scanf("%lld",&p[i]);
    vector<int> a(m);
    for(int i=0;i<m;i++) scanf("%d",&a[i]);
    vector<char> ops; ops.reserve(n-1);
    for(int v:a){ for(int i=0;i<v;i++) ops.push_back('A'); for(int i=0;i<v;i++) ops.push_back('B'); }
    vector<int> Larr(n),loarr(n),hiarr(n);
    {
        int L=1,lo=0,hi=0;
        Larr[0]=1;loarr[0]=0;hiarr[0]=0;
        for(int t=0;t+1<n;t++){
            if(ops[t]=='A'){ if(lo<hi) lo++; else L++; }
            else hi++;
            Larr[t+1]=L;loarr[t+1]=lo;hiarr[t+1]=hi;
        }
    }
    buildST();
    bool allOne=true; for(int v:a) if(v!=1) allOne=false;
    vector<ll> ans(q,0);
    if(allOne){
        vector<ll> prefM(n+2,0), prefAdj(n+2,0);
        for(int j=1;j<=n-1;j++) prefM[j]=prefM[j-1]+min(p[j],p[j+1]);
        auto M=[&](int j){return min(p[j],p[j+1]);};
        for(int t=1;t<=n-2;t++) prefAdj[t]=prefAdj[t-1]+max(M(t),M(t+1));
        for(int t=max(0,n-1);t<=n+1;t++) if(t>=1) prefAdj[t]=prefAdj[t-1];
        for(int i=0;i<q;i++){
            int x,l,r; scanf("%d %d %d",&x,&l,&r);
            if(x%2==1){ int k=(x-1)/2; ans[i]=prefM[r+k]-prefM[l+k-1]; }
            else { int k=x/2; int t1=l+k-1,t2=r+k-1; ans[i]=prefAdj[t2]-prefAdj[t1-1]; }
        }
    } else {
        // read queries
        vector<int> qx(q),ql(q),qr(q);
        for(int i=0;i<q;i++) scanf("%d %d %d",&qx[i],&ql[i],&qr[i]);
        // W==0 handle directly
        // W>0 group by L
        vector<Entry> ents;
        for(int i=0;i<q;i++){
            int x=qx[i]; int L=Larr[x],lo=loarr[x],hi=hiarr[x];
            if(hi==lo){
                // f(i)=getmin(i+lo,i+lo+L-1); sum
                ll s=0;
                for(int ii=ql[i];ii<=qr[i];ii++) s+=getmin(ii+lo,ii+lo+L-1);
                ans[i]=s;
            } else {
                ents.push_back({i,lo,hi,ql[i],qr[i]});
            }
        }
        // group by L
        sort(ents.begin(),ents.end(),[&](const Entry&A,const Entry&B){
            int La=Larr[qx[A.idx]], Lb=Larr[qx[B.idx]];
            return La<Lb;
        });
        int pos=0; int EN=ents.size();
        while(pos<EN){
            int La=Larr[qx[ents[pos].idx]];
            // build mL for this L
            int Mlen=n-La+1;
            vector<ll> mL(Mlen);
            for(int j=1;j<=Mlen;j++) mL[j-1]=getmin(j,j+La-1);
            SegTree seg; seg.build(mL);
            while(pos<EN && Larr[qx[ents[pos].idx]]==La){
                Entry&e=ents[pos];
                int lo=e.lo,hi=e.hi,l=e.l,r=e.r;
                int W=hi-lo;
                int cnt=r-l+1;
                // choose method
                double costA=(double)cnt + W;
                double costB=(double)cnt * (log2((double)max(1,Mlen))+1);
                ll s=0;
                if(costB<costA && cnt>0){
                    for(int i=l;i<=r;i++){
                        int j1=i+lo, j2=i+hi;
                        // j1,j2 are 1-indexed into mL -> 0-indexed j1-1,j2-1
                        s+=seg.qmax(j1-1,j2-1);
                    }
                } else {
                    int jstart=l+lo, jend=r+hi;
                    deque<int> dq;
                    int idx=0;
                    for(int j=jstart;j<=jend;j++){
                        ll v=mL[j-1];
                        while(!dq.empty() && mL[dq.back()]<=v) dq.pop_back();
                        dq.push_back(idx);
                        if(dq.front()<=idx-W) dq.pop_front();
                        if(idx>=W) s+=mL[dq.front()];
                        idx++;
                    }
                }
                ans[e.idx]=s;
                pos++;
            }
        }
    }
    for(int i=0;i<q;i++) printf("%lld\n",ans[i]);
    return 0;
}

