        auto M=[&](int j){return min(p[j],p[j+1]);};
        for(int t=1;t<=n-2;t++)prefAdj[t]=prefAdj[t-1]+max(M(t),M(t+1));
        for(int t=n-1;t<=n+1;t++)prefAdj[t]=prefAdj[t-1];
        for(int i=0;i<q;i++){int x=qx[i],l=ql[i],r=qr[i];if(x%2==1){int k=(x-1)/2;ans[i]=prefM[r+k]-prefM[l+k-1];}else{int k=x/2;int t1=l+k-1,t2=r+k-1;ans[i]=prefAdj[t2]-prefAdj[t1-1];}}
    } else {
        vector<Entry> ents;
        for(int i=0;i<q;i++){int x=qx[i];int L=Larr[x],lo=loarr[x],hi=hiarr[x];
            if(hi==lo){ll s=0;for(int ii=ql[i];ii<=qr[i];ii++)s+=getmin(ii+lo,ii+lo+L-1);ans[i]=s;}
            else ents.push_back({i,lo,hi,ql[i],qr[i]});
        }
        sort(ents.begin(),ents.end(),[&](const Entry&A,const Entry&B){return Larr[qx[A.idx]]<Larr[qx[B.idx]];});
        int pos=0,EN=ents.size();
