            int Mlen=n-La+1;
            vector<ll> mL(Mlen);
            for(int j=1;j<=Mlen;j++) mL[j-1]=getmin(j,j+La-1);
            int sz=1; while(sz<Mlen) sz*=2;
            vector<ll> t(2*sz,LLONG_MIN);
            for(int i=0;i<Mlen;i++) t[sz+i]=mL[i];
            for(int i=sz-1;i>=1;i--) t[i]=max(t[2*i],t[2*i+1]);
            while(pos<EN && Larr[qx[ents[pos].idx]]==La){
                Entry&e=ents[pos];
                int lo=e.lo,hi=e.hi,l=e.l,r=e.r;
                int W=hi-lo, cnt=r-l+1;
                double costA=(double)cnt+W;
                double costB=(double)cnt*(log2((double)max(1,Mlen))+1);
                ll s=0;
                if(costB<costA){
                    for(int i=l;i<=r;i++){
                        int j1=i+lo, j2=i+hi;
                        int a1=j1-1+sz,b1=j2-1+sz; ll res=LLONG_MIN;
                        while(a1<=b1){ if(a1&1) res=max(res,t[a1++]); if(!(b1&1)) res=max(res,t[b1--]); a1>>=1; b1>>=1; }
                        s+=res;
                    }
                } else {
                    int jstart=l+lo,jend=r+hi,sw=W+1;
                    vector<ll> mm; mm.reserve(jend-jstart+1);
                    for(int j=jstart;j<=jend;j++) mm.push_back(mL[j-1]);
                    deque<int> dq;
                    for(int idx=0;idx<(int)mm.size();idx++){
                        while(!dq.empty() && mm[dq.back()]<=mm[idx]) dq.pop_back();
                        dq.push_back(idx);
                        if(dq.front()<=idx-sw) dq.pop_front();
                        if(idx>=sw-1) s+=mm[dq.front()];
                    }
                }
                ans[e.idx]=s;
                pos++;
            }
        }
    }
    for(int i=0;i<q;i++) printf("%lld\n",ans[i]);
    return 0;
}

